        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by using an assignment operator (`=`) instead of a comparison operator (`==`) in the error handling conditions of the `write_all` and `read_all` functions. This led to the erroneous behavior where the condition always evaluated to true, causing the functions to incorrectly handle the `EINTR` error and potentially resulting in infinite loops or incorrect error returns.

        Commit message:
        Network backend: fix bug introduced by 4cb089b

Signed-off-by: Paul Cercueil <paul.cercueil@analog.com>  

        Patch:

 static ssize_t write_all(const void *src, size_t len, int fd)
 {
 	uintptr_t ptr = (uintptr_t) src;
 	while (len) {
 		ssize_t ret = send(fd, (const void *) ptr, (int) len, 0);
 		if (ret < 0) {
 #ifdef _WIN32
 			int err = WSAGetLastError();
 #else
 			int err = errno;
 #endif
-			if (err = EINTR)
+			if (err == EINTR)
 				continue;
 			return (ssize_t) -err;
 		}
 		ptr += ret;
 		len -= ret;
 	}
 	return (ssize_t)(ptr - (uintptr_t) src);
 }

 static ssize_t read_all(void *dst, size_t len, int fd)
 {
 	uintptr_t ptr = (uintptr_t) dst;
 	while (len) {
 		ssize_t ret = recv(fd, (void *) ptr, (int) len, 0);
 		if (ret < 0) {
 #ifdef _WIN32
 			int err = WSAGetLastError();
 #else
 			int err = errno;
 #endif
-			if (err = EINTR)
+			if (err == EINTR)
 				continue;
 			return (ssize_t) -err;
 		}
 		if (ret == 0)
 			return -EPIPE;
 		ptr += ret;
 		len -= ret;
 	}
 	return (ssize_t)(ptr - (uintptr_t) dst);
 }



